definitions.expression:
VAR vFiltered = 
			    FILTER('public metas_bruto', 
			        NOT ISBLANK('public metas_bruto'[cnpj_cpf]) 
			        && 'public metas_bruto'[cnpj_cpf] <> ""
			        && 'public metas_bruto'[data_lancamento] >= DATE(2026, 8, 3)
			    )

			VAR vAgrupado = 
			    SUMMARIZE(
			        vFiltered,
			        'public metas_bruto'[numero_contrato],
			        'public metas_bruto'[numero_documento_fiscal],
			        'public metas_bruto'[bandeira]
			    )

			VAR vBase = 
			    ADDCOLUMNS(
			        vAgrupado,
			        "cnpj_cpf", CALCULATE(MAX('public metas_bruto'[cnpj_cpf])),
			        "razao_social", CALCULATE(MAX('public metas_bruto'[razao_social])),
			        "descricao_cat", CALCULATE(MAX('public metas_bruto'[descricao_cat])),
			        "data_lancamento", CALCULATE(MAX('public metas_bruto'[data_lancamento])),
			        "HonorariosPorJob.honorario", CALCULATE(MAX('public metas_bruto'[HonorariosPorJob.honorario])),
			        "valor_bruto", CALCULATE(SUM('public metas_bruto'[valor_bruto])),
			        "codigo_lancamento_omie", CALCULATE(MAX('public metas_bruto'[codigo_lancamento_omie]))
			    )

			VAR vRecebido = 
			    ADDCOLUMNS(
			        vBase,
			        "UNIDADE_ID_VAL",
			        VAR curJob = [numero_contrato]
			        VAR curCnpj = [cnpj_cpf]
			        VAR idFromJob = CALCULATE(
			            MAX('vw_powerbi_job_repasse'[UNIDADE_ID]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        )
			        VAR idFromPU = CALCULATE(
			            MAX('vw_participantes_unidades'[UNIDADE_ID]),
			            FILTER('vw_participantes_unidades', 
			                (NOT ISBLANK('vw_participantes_unidades'[PARTICIPANTE_CPF]) && 'vw_participantes_unidades'[PARTICIPANTE_CPF] = curCnpj) || 
			                (NOT ISBLANK('vw_participantes_unidades'[CNPJ_UNIDADE]) && 'vw_participantes_unidades'[CNPJ_UNIDADE] = curCnpj)
			            )
			        )
			        VAR finalId = COALESCE(idFromJob, idFromPU)
			        RETURN
			        IF(ISBLANK(finalId), "", FORMAT(finalId, "0")),

			        "NOME_UNIDADE_VAL", 
			        VAR curJob = [numero_contrato]
			        VAR curCnpj = [cnpj_cpf]
			        VAR nomeFromJob = CALCULATE(
			            MAX('vw_powerbi_job_repasse'[UNIDADE_NOME]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        )
			        VAR nomeFromPU = CALCULATE(
			            MAX('vw_participantes_unidades'[UNIDADE_NOME]),
			            FILTER('vw_participantes_unidades', 
			                (NOT ISBLANK('vw_participantes_unidades'[PARTICIPANTE_CPF]) && 'vw_participantes_unidades'[PARTICIPANTE_CPF] = curCnpj) || 
			                (NOT ISBLANK('vw_participantes_unidades'[CNPJ_UNIDADE]) && 'vw_participantes_unidades'[CNPJ_UNIDADE] = curCnpj)
			            )
			        )
			        RETURN
			        COALESCE(nomeFromJob, nomeFromPU, ""),

			        "JOB_VAL", [numero_contrato],
			        "DATA_CADASTRO_VAL", 
			        VAR curJob = [numero_contrato]
			        VAR curCnpj = [cnpj_cpf]
			        VAR dtFromJob = CALCULATE(
			            MAX('vw_powerbi_job_repasse'[DATA_CADASTRO]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        )
			        VAR dtFromPU = CALCULATE(
			            MAX('vw_participantes_unidades'[VIGENCIA_INICIO]),
			            FILTER('vw_participantes_unidades', 
			                (NOT ISBLANK('vw_participantes_unidades'[PARTICIPANTE_CPF]) && 'vw_participantes_unidades'[PARTICIPANTE_CPF] = curCnpj) || 
			                (NOT ISBLANK('vw_participantes_unidades'[CNPJ_UNIDADE]) && 'vw_participantes_unidades'[CNPJ_UNIDADE] = curCnpj)
			            )
			        )
			        RETURN
			        COALESCE(dtFromJob, dtFromPU, [data_lancamento]),

			        "GROSSUP_VAL",
			        VAR curJob = [numero_contrato]
			        VAR valGrossup = CALCULATE(
			            MAX('vw_powerbi_job_repasse'[COBRANCA_GROSSUP]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        )
			        RETURN
			        IF(ISBLANK(valGrossup), "-", IF(valGrossup = "S" || valGrossup = "Sim" || valGrossup = "1", "Sim", "Não")),
			        "IMPOSTO_VAL",
			        VAR curJob = [numero_contrato]
			        VAR valImposto = CALCULATE(
			            MAX('vw_powerbi_job_repasse'[UNIRETEMIMPOSTO]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        )
			        RETURN
			        IF(ISBLANK(valImposto), "-", IF(valImposto = "0" || valImposto = "S" || valImposto = "Sim" || valImposto = "1", "Sim", "Não")),
			        "RETENCAO_VAL",
			        VAR curJob = [numero_contrato]
			        RETURN
			        CALCULATE(
			            MAX('vw_powerbi_job_repasse'[RETENCAO]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        ),
			        "REDE_DISTRIBUICAO_VAL",
			        VAR curJob = [numero_contrato]
			        RETURN
			        CALCULATE(
			            MAX('vw_powerbi_job_repasse'[REDE_DISTRIBUICAO]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        ),
			        "REDE_DISTRIBUICAO_OLD_VAL",
			        VAR curJob = [numero_contrato]
			        RETURN
			        CALCULATE(
			            MAX('vw_powerbi_job_repasse'[REDE_DISTRIBUICAO_OLD]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        ),
			        "PARTICIPANTE_FRANQUEADO_VAL",
			        VAR curJob = [numero_contrato]
			        RETURN
			        CALCULATE(
			            MAX('vw_powerbi_job_repasse'[PARTICIPANTE_FRANQUEADO]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        ),
			        "PARTICIPANTE_CLIENTE_VAL",
			        VAR curJob = [numero_contrato]
			        RETURN
			        CALCULATE(
			            MAX('vw_powerbi_job_repasse'[PARTICIPANTE_CLIENTE]),
			            FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = curJob)
			        )
			    )

			VAR vJsonRows =
			    CONCATENATEX(
			        vRecebido,
			        VAR curRede = UPPER(COALESCE([REDE_DISTRIBUICAO_VAL], ""))
			        VAR curRedeOld = UPPER(COALESCE([REDE_DISTRIBUICAO_OLD_VAL], ""))
			        VAR curUnidadeId = COALESCE([UNIDADE_ID_VAL], "")
			        VAR curUnidadeNome = UPPER(COALESCE([NOME_UNIDADE_VAL], ""))
			        VAR curPartFranq = UPPER(TRIM(COALESCE([PARTICIPANTE_FRANQUEADO_VAL], "")))
			        VAR curPartCli = UPPER(TRIM(COALESCE([PARTICIPANTE_CLIENTE_VAL], "")))
			        VAR isMesmoParticipante = (curPartFranq <> "" && curPartCli <> "" && curPartFranq = curPartCli)
			        VAR isBloqueado = 
			            CONTAINSSTRING(curRede, "STORE") ||
			            CONTAINSSTRING(curRede, "XP") ||
			            CONTAINSSTRING(curRedeOld, "STORE") ||
			            CONTAINSSTRING(curRedeOld, "XP") ||
			            curUnidadeId = "2153" ||
			            CONTAINSSTRING(curUnidadeNome, "STUDIO CONTABILIDADE LTDA - PILOTO") ||
			            isMesmoParticipante
			        VAR isGrossup = ([GROSSUP_VAL] = "Sim")
			        VAR curBaseValor = IF(isGrossup, DIVIDE([valor_bruto], 1.1425, 0), [valor_bruto])
			        VAR percFromJob = CALCULATE(MAX('vw_powerbi_job_repasse'[PERC_HONORARIOS_JOB]), FILTER('vw_powerbi_job_repasse', 'vw_powerbi_job_repasse'[JOB] = [JOB_VAL]))
			VAR percFromTable = CALCULATE(MAX('HonorariosPorJob'[honorario]), FILTER('HonorariosPorJob', 'HonorariosPorJob'[numero_contrato] = [JOB_VAL]))
			VAR curUidNum = IF(ISBLANK(curUnidadeId) || curUnidadeId = "", BLANK(), VALUE(curUnidadeId))
			VAR percFromPU = CALCULATE(MAX('vw_participantes_unidades'[PERC_FRANQUEADO]), FILTER('vw_participantes_unidades', 'vw_participantes_unidades'[UNIDADE_ID] = curUidNum))
			VAR curPercHonorario = IF(
			    isBloqueado, 
			    0, 
			    COALESCE(
			        IF(percFromPU > 0, percFromPU, BLANK()),
			        IF(percFromJob > 0, percFromJob, BLANK()), 
			        IF(percFromTable > 0, percFromTable, BLANK()), 
			        [HonorariosPorJob.honorario], 
			        0
			    )
			)
			        VAR curVlRepasseBruto = curBaseValor * DIVIDE(curPercHonorario, 100, 0)
			        VAR curRetencao = COALESCE([RETENCAO_VAL], 0)
			        VAR curVlRetencao = curVlRepasseBruto * DIVIDE(curRetencao, 100, 0)
			        VAR curVlRepasseLiquido = curVlRepasseBruto - curVlRetencao
			        RETURN
			        "{" &
			            "id:'" & [codigo_lancamento_omie] & "'" &
			            ",cnpj:'" & [cnpj_cpf] & "'" &
			            ",nome:'" & SUBSTITUTE(SUBSTITUTE([razao_social], UNICHAR(39), " "), UNICHAR(34), " ") & "'" &
			            ",bandeira:'" & COALESCE([bandeira], "") & "'" &
			            ",categoria:'" & SUBSTITUTE(SUBSTITUTE([descricao_cat], UNICHAR(39), " "), UNICHAR(34), " ") & "'" &
			            ",valor:" & SUBSTITUTE(FORMAT([valor_bruto], "0.00"), ",", ".") &
			            ",nf:'" & COALESCE([numero_documento_fiscal], "") & "'" &
			            ",nfCliente:''" &
			            ",dataNfCliente:''" &
			            ",obsNfCliente:''" &
			            ",dataAprovacao:''" &
			            ",dataPagamento:'" & FORMAT([data_lancamento], "dd/MM/yyyy") & "'" &
			            ",unidade:'" & COALESCE([UNIDADE_ID_VAL], "") & "'" &
			            ",nomeUnidade:'" & SUBSTITUTE(SUBSTITUTE(COALESCE([NOME_UNIDADE_VAL], ""), UNICHAR(39), " "), UNICHAR(34), " ") & "'" &
			            ",grossup:'" & [GROSSUP_VAL] & "'" &
			            ",imposto:'" & [IMPOSTO_VAL] & "'" &
			            ",retencao:" & SUBSTITUTE(FORMAT(curRetencao, "0.00"), ",", ".") &
			            ",valorRetencao:" & SUBSTITUTE(FORMAT(curVlRetencao, "0.00"), ",", ".") &
			            ",percHonorario:" & SUBSTITUTE(FORMAT(curPercHonorario, "0.0000"), ",", ".") &
			            ",valorUnit:" & SUBSTITUTE(FORMAT(curVlRepasseLiquido, "0.00"), ",", ".") &
			            ",status:'Pendente'" &
			            ",job:'" & COALESCE([JOB_VAL], "") & "'" &
			            ",dataCadastro:'" & IF(ISBLANK([DATA_CADASTRO_VAL]), "", FORMAT([DATA_CADASTRO_VAL], "dd/MM/yyyy")) & "'" &
			            ",dataPgtoRepasse:''" &
			        "}",
			        ",", [codigo_lancamento_omie], ASC
			    )

			VAR vTotalValor = SUMX(vRecebido, [valor_bruto])
			VAR vCountRows = COUNTROWS(vRecebido)
			VAR vCountUnidades = COUNTROWS(DISTINCT(SELECTCOLUMNS(FILTER(vRecebido, [UNIDADE_ID_VAL] <> ""), "u", [UNIDADE_ID_VAL])))

			VAR _css = "<style>
			:root{--bg-dark:#0a0e1a;--bg-panel:#0d1120;--bg-header:#111628;--bg-card:#141a2e;--bg-row-even:#0f1424;--bg-row-odd:#111829;--text-main:#e8eaf0;--text-muted:#6b7394;--text-dim:#4a5270;--gold:#D4AF37;--gold-bright:#FFD700;--gold-dim:rgba(212,175,55,0.15);--green:#00e676;--green-dim:rgba(0,230,118,0.12);--red:#ff1744;--red-dim:rgba(255,23,68,0.12);--blue:#64b5f6;--border:#1a2040;--border-gold:rgba(212,175,55,0.25);}
			*{box-sizing:border-box;margin:0;padding:0;}
			body{font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;background:var(--bg-dark);color:var(--text-main);overflow:hidden;}
			.app{display:flex;flex-direction:column;width:100vw;height:100vh;}
			.header{flex-shrink:0;height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:linear-gradient(135deg,var(--bg-header) 0%,#0e1225 100%);border-bottom:1px solid var(--gold);box-shadow:0 2px 20px rgba(212,175,55,0.08);}
			.logo{font-size:21px;font-weight:900;letter-spacing:2px;color:var(--gold);text-shadow:0 0 12px rgba(212,175,55,0.25);}
			.header-title{font-size:16px;font-weight:400;letter-spacing:4px;color:var(--text-muted);text-transform:uppercase;}
			.summary{flex-shrink:0;display:flex;gap:16px;padding:14px 28px;background:var(--bg-panel);border-bottom:1px solid var(--border);}
			.card{flex:1;padding:14px 20px;border-radius:12px;background:linear-gradient(145deg,var(--bg-card) 0%,#181f38 100%);border:1px solid var(--border);position:relative;overflow:hidden;transition:transform 0.2s,box-shadow 0.2s;}
			.card:hover{transform:translateY(-2px);box-shadow:0 4px 24px rgba(0,0,0,0.4);}
			.card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--gold),var(--gold-bright),var(--gold));}
			.card-label{font-size:13px;font-weight:600;letter-spacing:2px;text-transform:uppercase;color:var(--text-muted);margin-bottom:4px;}
			.card-value{font-size:23px;font-weight:800;color:var(--text-main);}
			.card-value .currency{font-size:16px;color:var(--text-muted);font-weight:600;margin-right:4px;}
			.card-sub{font-size:13px;color:#ffb74d;font-weight:700;margin-top:3px;}
			.controls{flex-shrink:0;display:flex;align-items:center;gap:12px;padding:10px 28px;background:var(--bg-panel);border-bottom:1px solid var(--border);}
			.search-box{flex:1;max-width:260px;}
			.search-box input{width:100%;padding:7px 14px;border-radius:8px;border:1px solid var(--border);background:var(--bg-card);color:var(--text-main);font-size:15px;outline:none;transition:border 0.2s;}
			.search-box input:focus{border-color:var(--gold);}
			.date-popover-container{position:relative;display:inline-block;}
			.date-trigger-btn{display:flex;align-items:center;gap:6px;}
			.date-trigger-btn.has-filter{border-color:var(--gold);color:var(--gold);background:var(--gold-dim);}
			.date-popover{display:none;position:absolute;top:calc(100% + 8px);left:0;z-index:1000;background:var(--bg-card);border:1px solid var(--gold);border-radius:10px;padding:14px;width:260px;box-shadow:0 8px 30px rgba(0,0,0,0.6);}
			.date-popover.show{display:block;animation:fadeIn 0.2s ease forwards;}
			.date-popover-header{display:flex;align-items:center;justify-content:space-between;font-size:12px;font-weight:700;color:var(--gold);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:10px;border-bottom:1px solid var(--border);padding-bottom:6px;}
			.btn-popover-close{background:transparent;border:none;color:var(--text-muted);font-size:18px;cursor:pointer;line-height:1;}
			.btn-popover-close:hover{color:var(--red);}
			.date-popover-body{display:flex;flex-direction:column;gap:10px;margin-bottom:12px;}
			.date-field{display:flex;flex-direction:column;gap:4px;}
			.date-field label{font-size:11px;color:var(--text-muted);font-weight:600;text-transform:uppercase;letter-spacing:0.5px;}
			.date-input-pop{background:var(--bg-dark);border:1px solid var(--border);border-radius:6px;color:var(--text-main);padding:6px 10px;font-size:13px;outline:none;font-family:inherit;color-scheme:dark;transition:border-color 0.2s;}
			.date-input-pop:focus{border-color:var(--gold);}
			.date-popover-footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--border);padding-top:10px;}
			.filter-btn{padding:6px 14px;border-radius:8px;border:1px solid var(--border);background:var(--bg-card);color:var(--text-muted);font-size:14px;font-weight:600;cursor:pointer;transition:all 0.2s;letter-spacing:0.5px;}
			.filter-btn:hover,.filter-btn.active{border-color:var(--gold);color:var(--gold);background:var(--gold-dim);}
			.count-badge{margin-left:auto;font-size:14px;color:var(--text-muted);font-weight:600;}
			.btn-save{padding:7px 20px;border-radius:8px;border:1px solid var(--green);background:var(--green-dim);color:var(--green);font-size:15px;font-weight:700;cursor:pointer;transition:all 0.25s;letter-spacing:0.5px;text-transform:uppercase;}
			.btn-save:hover{background:var(--green);color:#0a0e1a;box-shadow:0 0 16px rgba(0,230,118,0.35);}
			.btn-save:active{transform:scale(0.96);}
			.btn-save.has-changes{animation:pulse-green 1.5s infinite;}
			@keyframes pulse-green{0%,100%{box-shadow:0 0 0 0 rgba(0,230,118,0.4)}50%{box-shadow:0 0 12px 4px rgba(0,230,118,0.2)}}
			.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%) translateY(80px);background:#1a2e1a;border:1px solid var(--green);color:var(--green);padding:12px 28px;border-radius:10px;font-size:16px;font-weight:700;z-index:9999;opacity:0;transition:all 0.4s ease;box-shadow:0 8px 32px rgba(0,230,118,0.2);}
			.toast.show{opacity:1;transform:translateX(-50%) translateY(0);}
			.table-wrap{flex:1;overflow-y:auto;padding:0 28px 14px;}
			.table-wrap::-webkit-scrollbar{width:5px;}
			.table-wrap::-webkit-scrollbar-track{background:var(--bg-dark);}
			.table-wrap::-webkit-scrollbar-thumb{background:var(--border);border-radius:3px;}
			table{width:100%;border-collapse:separate;border-spacing:0;font-size:15px;}
			thead th{position:sticky;top:0;z-index:10;background:var(--bg-header);color:var(--gold);font-weight:700;padding:10px 8px;text-transform:uppercase;letter-spacing:1px;border-bottom:1px solid var(--gold);font-size:13px;text-align:left;white-space:nowrap;cursor:pointer;user-select:none;}
			thead th.num{text-align:right;}
			tbody tr{transition:background 0.15s;}
			tbody tr:nth-child(even){background:var(--bg-row-even);}
			tbody tr:nth-child(odd){background:var(--bg-row-odd);}
			tbody tr:hover{background:#1a2245;}
			td{padding:9px 8px;border-bottom:1px solid var(--border);text-align:left;white-space:nowrap;}
			td.num{text-align:right;}
			.cnpj{font-family:Consolas,monospace;font-size:14px;color:var(--text-main);}
			.nome{font-weight:600;color:var(--text-main);}
			.valor{color:var(--gold-bright);font-weight:700;}
			.unidade-code{display:inline-block;padding:2px 8px;border-radius:4px;background:var(--gold-dim);color:var(--text-main);font-size:13px;font-weight:700;}
			.perc{font-weight:600;color:var(--text-main);}
			.input-nf-cliente{width:90px;padding:4px 8px;border-radius:6px;border:1px dashed var(--border-gold);background:rgba(10,14,26,0.7);color:var(--gold-bright);font-size:13px;font-family:inherit;outline:none;transition:all 0.2s;text-align:center;}
			.input-nf-cliente:focus{border:1px solid var(--gold);background:var(--bg-card);box-shadow:0 0 8px rgba(212,175,55,0.35);}
			.input-nf-cliente::placeholder{color:var(--text-dim);font-size:11px;}
			.input-data-pgto-cell{width:115px;padding:3px 6px;border-radius:6px;border:1px dashed rgba(56,189,248,0.4);background:rgba(10,14,26,0.7);color:#38bdf8;font-size:12px;font-family:inherit;outline:none;transition:all 0.2s;color-scheme:dark;}
			.input-data-pgto-cell:focus{border:1px solid #38bdf8;background:var(--bg-card);box-shadow:0 0 8px rgba(56,189,248,0.3);}
			.data-pgto-box{display:inline-flex;align-items:center;gap:5px;background:rgba(56,189,248,0.08);padding:3px 7px;border-radius:6px;border:1px solid rgba(56,189,248,0.25);}
			.nf-cliente-box{display:inline-flex;align-items:center;gap:5px;background:rgba(212,175,55,0.06);padding:3px 7px;border-radius:6px;border:1px solid rgba(212,175,55,0.18);}
			.nf-cliente-text{font-family:Consolas,monospace;font-weight:700;color:var(--gold-bright);font-size:13px;}
			.btn-edit-nf{background:transparent;border:none;color:var(--text-muted);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;padding:2px;border-radius:4px;transition:all 0.2s;}
			.btn-edit-nf:hover{color:var(--gold);transform:scale(1.15);}
			.btn-view-obs{background:transparent;border:none;color:var(--blue);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;padding:2px;border-radius:4px;transition:all 0.2s;}
			.btn-view-obs:hover{color:#90caf9;transform:scale(1.15);}
			.status-btn-group{display:flex;align-items:center;justify-content:flex-end;gap:4px;}
			.status-btn{width:24px;height:24px;border-radius:6px;border:1px solid var(--border);background:var(--bg-card);color:var(--text-muted);font-size:13px;font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all 0.2s;}
			.status-btn:hover{border-color:var(--gold);color:var(--gold);}
			.status-btn.active-p{background:rgba(255,145,0,0.15);border-color:#ff9100;color:#ff9100;}
			.status-btn.active-v{background:rgba(56,189,248,0.18);border-color:#38bdf8;color:#38bdf8;}
